"use client";

import { signIn } from "next-auth/react";
import { useState } from "react";
import { useRouter } from "next/navigation";

export default function SignInPage() {
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const router = useRouter();

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError("");
    setLoading(true);

    const form = e.currentTarget;

    const res = await signIn("credentials", {
      email: form.email.value,
      password: form.password.value,
      redirect: false,
    });

    setLoading(false);

    if (res?.error) {
      setError("E-mail of wachtwoord klopt niet.");
      return;
    }

    // 🔥 Daha doğru yönlendirme
    router.push("/");
  }

  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-50 p-6">
      
      <div className="w-full max-w-sm bg-white p-8 rounded-2xl shadow-md border">
        
        <h1 className="text-3xl font-bold mb-2 text-center">
          Inloggen
        </h1>

        <p className="text-sm text-gray-500 text-center mb-6">
          Welkom terug! Log in om verder te gaan.
        </p>

        <form onSubmit={handleSubmit} className="space-y-4">
          
          <input
            type="email"
            name="email"
            placeholder="E-mail"
            className="w-full p-3 border rounded-xl bg-gray-50 focus:outline-none focus:ring-2 focus:ring-black"
            required
          />

          <input
            type="password"
            name="password"
            placeholder="Wachtwoord"
            className="w-full p-3 border rounded-xl bg-gray-50 focus:outline-none focus:ring-2 focus:ring-black"
            required
          />

          {error && (
            <p className="text-red-500 text-sm">{error}</p>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-black text-white p-3 rounded-xl font-medium hover:bg-gray-800 transition disabled:opacity-50"
          >
            {loading ? "Bezig..." : "Inloggen"}
          </button>
        </form>

        {/* 🔥 Extra */}
        <p className="text-sm text-gray-500 text-center mt-6">
          Nog geen account?{" "}
          <a href="/auth/signup" className="text-black font-medium hover:underline">
            Registreren
          </a>
        </p>
      </div>
    </div>
  );
}